class PathIterationResultAdmissionTest {

	private static final ValueFactory VF = SimpleValueFactory.getInstance();
	private static final String NS = "urn:path-admission:";
	private static final IRI PREDICATE = VF.createIRI(NS + "edge");

	@ParameterizedTest(name = "minimum length {0}")
	@ValueSource(longs = { 0, 1 })
	void admittingNewResultsHashesEachEndpointAtMostOnce(long minimumLength) {
		int edges = 16;
		ListTripleSource source = new ListTripleSource();
		List<CountingIri> nodes = new ArrayList<>();
		for (int i = 0; i <= edges; i++) {
			nodes.add(new CountingIri(i));
		}
		for (int i = 0; i < edges; i++) {
			source.statements.add(VF.createStatement(nodes.get(i), PREDICATE, nodes.get(i + 1)));
		}
		ArbitraryLengthPath path = path(minimumLength);
		DefaultEvaluationStrategy strategy = new DefaultEvaluationStrategy(source, null);
		var prepared = strategy.precompile(path, new QueryEvaluationContext.Minimal(null));
		nodes.forEach(node -> node.hashCalls = 0);
		List<Value> actual = new ArrayList<>();
		try (var rows = prepared.evaluate(EmptyBindingSet.getInstance())) {
			while (rows.hasNext()) {
				actual.add(rows.next().getValue("o"));
			}
		}
		// The anchor is a plain IRI. The source does only linear equality checks, and collection into this list
		// does not hash endpoints. Snapshot before assertion helpers may hash the returned RDF values themselves.
		int endpointHashes = nodes.stream().skip(1).mapToInt(node -> node.hashCalls).sum();
		assertThat(actual).containsExactlyInAnyOrderElementsOf(nodes.subList((int) minimumLength, nodes.size()));
		assertThat(source.closed).isEqualTo(source.opened);
		assertThat(endpointHashes).as("the source endpoints must exercise result admission").isPositive();
		assertThat(endpointHashes)
				.as("new path results must use one set insertion instead of a membership probe followed by insertion")
				.isLessThanOrEqualTo(edges);
	}

	@ParameterizedTest(name = "minimum length {0}")
	@ValueSource(longs = { 0, 1 })
	void subclassAdmissionHookRunsOnlyForDistinctResults(long minimumLength) {
		ListTripleSource source = new ListTripleSource();
		// The diamond reaches n3 twice; the closing edge makes the start a nonzero-length result as well.
		for (int[] edge : new int[][] { { 0, 1 }, { 0, 2 }, { 1, 3 }, { 2, 3 }, { 3, 0 } }) {
			source.statements.add(VF.createStatement(node(edge[0]), PREDICATE, node(edge[1])));
		}
		ArbitraryLengthPath path = path(minimumLength);
		DefaultEvaluationStrategy strategy = new DefaultEvaluationStrategy(source, null);
		List<Value> actual = new ArrayList<>();
		try (HookedPathIteration rows = new HookedPathIteration(strategy, path)) {
			while (rows.hasNext()) {
				actual.add(rows.next().getValue("o"));
			}
			assertThat(actual).containsExactlyInAnyOrder(node(0), node(1), node(2), node(3));
			assertThat(rows.addCalls).as("the protected hook must see each admitted answer once").isEqualTo(4);
			assertThat(rows.duplicateAddCalls).as("duplicate answers must not reach the protected add hook").isZero();
		}
		assertThat(source.closed).isEqualTo(source.opened);
	}

	private static ArbitraryLengthPath path(long minimumLength) {
		Var start = Var.of("s", node(0), true, true);
		Var end = Var.of("o");
		StatementPattern step = new StatementPattern(start.clone(), Var.of("p", PREDICATE, true, true), end.clone());
		return new ArbitraryLengthPath(Scope.DEFAULT_CONTEXTS, start, step, end, minimumLength);
	}

	private static IRI node(int index) {
		return VF.createIRI(NS + "n" + index);
	}

	private static final class CountingIri extends SimpleIRI {
		private static final long serialVersionUID = 1L;
		private int hashCalls;

		private CountingIri(int index) {
			super(NS + "n" + index);
		}

		@Override
		public int hashCode() {
			hashCalls++;
			return super.hashCode();
		}
	}

	private static final class HookedPathIteration extends PathIteration {
		private int addCalls;
		private int duplicateAddCalls;

		private HookedPathIteration(DefaultEvaluationStrategy strategy, ArbitraryLengthPath path) {
			super(strategy, path.getScope(), path.getSubjectVar(), path.getPathExpression(), path.getObjectVar(), null,
					path.getMinLength(), EmptyBindingSet.getInstance());
		}

		@Override
		protected boolean add(Set<BindingSet> values, ValuePair pair) {
			addCalls++;
			boolean added = super.add(values, pair);
			if (!added) {
				duplicateAddCalls++;
			}
			return added;
		}
	}

	/** Keep lookup and fixture construction free of RDF-value hashing. */
	private static final class ListTripleSource implements TripleSource {
		private final List<Statement> statements = new ArrayList<>();
		private int opened;
		private int closed;

		@Override
		public CloseableIteration<? extends Statement> getStatements(Resource subject, IRI predicate, Value object,
				Resource... contexts) {
			List<Statement> matches = new ArrayList<>();
			for (Statement statement : statements) {
				if ((subject == null || subject.equals(statement.getSubject()))
						&& (predicate == null || predicate.equals(statement.getPredicate()))
						&& (object == null || object.equals(statement.getObject()))
						&& matchesContext(statement, contexts)) {
					matches.add(statement);
				}
			}
			opened++;
			return new CloseableIteratorIteration<Statement>(matches.iterator()) {
				@Override
				protected void handleClose() {
					closed++;
				}
			};
		}

		private static boolean matchesContext(Statement statement, Resource[] contexts) {
			if (contexts.length == 0) {
				return true;
			}
			for (Resource context : contexts) {
				if (Objects.equals(context, statement.getContext())) {
					return true;
				}
			}
			return false;
		}

		@Override
		public ValueFactory getValueFactory() {
			return VF;
		}
	}
}
